const params = $input.first().json.query || {};
const challenge = params['hub.challenge'] || '';
const verifyToken = params['hub.verify_token'] || '';
const expectedToken = 'livskin_wa_webhook_2026';

if (verifyToken === expectedToken && challenge) {
  return [{ json: { response: challenge, statusCode: 200 } }];
} else {
  return [{ json: { response: 'forbidden', statusCode: 403 } }];
}

// === PARSER + RESPONDER (Yossie) — sync con infra/n8n/lib/yossie_responder.js ===
// Doctrina #11: deterministic, NO IA fallback.

const DAYS_OF_WEEK = { domingo:0,dom:0,lunes:1,lun:1,martes:2,mar:2,miercoles:3,'miércoles':3,mie:3,'mié':3,mier:3,jueves:4,jue:4,viernes:5,vie:5,sabado:6,'sábado':6,sab:6,'sáb':6 };
const INTENT_PATTERNS = {
  confirm: /^\s*(s[ií]+|ok+|dale|perfecto|confirmo|listo|de\s*acuerdo|me\s*sirve|est[áa]\s*bien|esta\s*perfect|👍|✅)([\s,.!]+(perfecto|listo|claro|excelente|genial|👍|✅))*\s*[.!]*\s*$/i,
  reject: /^\s*(no|no\s*me\s*sirve|no\s*puedo|no\s*podr[ée]|no\s*podemos|❌)\s*[.!]*\s*$/i,
  ask_price: /(cu[áa]nto|precio|costo|cuesta|tarifa|cobr[áa]n|paga[mr]|valor)\b/i,
  ask_human: /(hablar\s+(con(\s+la|\s+el)?|al?)\s+(doctora?|m[eé]dica?|humana?|alguien|persona|ti|ud|usted)|atenderme|que\s+me\s+atienda|llam[aoe]r(me)?|tel[eé]fono|hablar\s+contigo)/i,
  ask_info: /(qu[ée]\s+es|c[oó]mo\s+(funciona|es|hace)|info|informaci[oó]n|me\s+puede[sn]?\s+(decir|contar|explicar)|necesito\s+saber)/i,
  greeting: /^\s*(hola|buenas|buen\s*d[ií]a|buenas\s*tardes|buenas\s*noches|saludos|hi|hello)\b/i,
  cancel: /(cancel[aoe]r|anul[aoe]r|ya\s*no\s*quiero|no\s*ir[ée]|no\s*podr[ée]\s*ir)\b/i,
  reschedule: /(reagend[aoe]r|reprogram[aoe]r|cambi[aoe]r\s+(fecha|d[ií]a|hora)|otra\s*fecha|otro\s*d[ií]a)\b/i,
};
const REFERRAL_PRODUCT_PATTERNS = {
  botox: /\b(botox|toxina|arrugas|expresi[óo]n|tercio)\b/i,
  acido: /(\b(acido|[áa]cido)\s+(hialuronico|hialur[óo]nico)\b)|\bhialur[óo]nico\b|\brinomodelaci[óo]n\b/i,
  prp: /\b(prp|plasma|plaquetas)\b/i,
  limpieza: /(limpieza\s+facial|facial\s+profunda)/i,
};
const RED_FLAG_PATTERNS = {
  contraindication: /\b(embaraz|gestaci[óo]n|c[áa]ncer|lupus|autoinmune|alergi[ac]\s+grave|lactancia|amamantando|anticoagulant|warfarina)\b/i,
  aggressive_negotiation: /\b(reg[áa]l[ao]me?|gratis|invita\s+la\s+casa|b[áa]j[au][lm]e|h[áa]z[mt]e\s+un\s+gran\s+descuento|m[áa]s\s+barato\s+que)\b/i,
  impossible_expectations: /\b(borrar\s+(todas?\s+)?mis?\s+arrugas|c[áa]mbiame\s+la\s+cara|garantizado\s+100|sin\s+ning[úu]n\s+riesgo)\b/i,
  aggressive_language: /\b(idiota|est[úu]pid[oa]|imb[éé]cil|estafa|fraude|tramposo)\b/i,
};
const PAINPOINT_PATTERNS = {
  miedo_dolor: /\b(duele|dolor|me\s+va\s+a\s+doler|sufre|sufrir|adormecimiento)\b/i,
  miedo_cambio: /\b(cambiar?\s+(la?\s+)?(rostro|cara)|que\s+me\s+cambies?|raro|congelad[ao]|aparecer\s+congelad)\b/i,
  precio_alto: /\b(caro|costoso|muy\s+alto|por\s+el\s+precio|fuera\s+de\s+mi\s+presupuesto|no\s+me\s+alcanza)\b/i,
  desconfianza: /\b(colegiada|certificad|m[ée]dica?\s+real|t[íi]tulo|estudios?)\b/i,
  inseguridad_social: /\b(pareja\s+note|esposo|que\s+digan|que\s+dir[áa]n)\b/i,
  timing_edad: /\b(muy\s+joven|muy\s+vieja|edad\s+correcta|mi\s+edad)\b/i,
  falta_tiempo: /\b(no\s+tengo\s+tiempo|horario|fin\s+de\s+semana|domingo)\b/i,
  comparacion: /\b(otra\s+cl[íi]nica|cobran\s+menos|munay|beysa|valderma)\b/i,
  distancia: /\b(vivo\s+en|lejos|viene\s+de|distancia|viajar|desde\s+lima|desde\s+arequipa)\b/i,
  cuotas: /\b(cr[ée]dito|cuotas|tarjeta\s+cr[ée]dito|pagar\s+despu[ée]s)\b/i,
  no_sabe: /\b(no\s+s[ée]\s+qu[ée]|qu[ée]\s+me\s+recomiendas?|cu[áa]l\s+me\s+conviene|qu[ée]\s+necesito)\b/i,
  primera_vez: /\b(primera\s+vez|nunca\s+me\s+he\s+hecho|primer\s+tratamiento)\b/i,
};
function normalize(t){return typeof t==='string'?t.trim().toLowerCase():''}
function stripAccents(s){return s.normalize('NFD').replace(/[\u0300-\u036f]/g,'')}
function detectIntent(text){let intent='unknown';let conf=0;if(INTENT_PATTERNS.ask_price.test(text)){intent='ask_price';conf=0.9}else if(INTENT_PATTERNS.ask_human.test(text)){intent='ask_human';conf=0.9}else if(INTENT_PATTERNS.cancel.test(text)){intent='cancel';conf=0.85}else if(INTENT_PATTERNS.reschedule.test(text)){intent='reschedule';conf=0.85}else if(INTENT_PATTERNS.confirm.test(text)){intent='confirm';conf=0.95}else if(INTENT_PATTERNS.reject.test(text)){intent='reject';conf=0.9}else if(INTENT_PATTERNS.ask_info.test(text)){intent='ask_info';conf=0.7}else if(INTENT_PATTERNS.greeting.test(text)){intent='greeting';conf=0.8}return{intent,confidence:conf}}
function detectProduct(text){if(!text)return null;for(const[p,re]of Object.entries(REFERRAL_PRODUCT_PATTERNS))if(re.test(text))return p;return null}
function detectRedFlag(text){for(const[t,re]of Object.entries(RED_FLAG_PATTERNS))if(re.test(text))return t;return null}
function detectPainpoint(text){for(const[t,re]of Object.entries(PAINPOINT_PATTERNS))if(re.test(text))return t;return null}
function detectInfo(text){const t=(text||'').toLowerCase();if(/(direcci[óo]n|d[óo]nde\s+(est[áa]n|queda)|ubicaci[óo]n|c[óo]mo\s+llegar)/i.test(t))return'direccion';if(/(pago|forma\s+de\s+pago|yape|plin|tarjeta|efectivo)/i.test(t))return'pagos';if(/(horario|cu[áa]ndo\s+atienden|domingos?|s[áa]bados?)/i.test(t))return'horario';return null}

// === COPY (extraído de docs/brand/) ===
const COPY = {
  greeting_botox: n => `Hola${n?' '+n:''} ☺️ Gracias por escribirnos a Livskin.\n\nSoy Yossie, asistente de la Dra. Claudia Delgado.\n\nTe aclaro los precios del Botox:\n• S/250 por zona individual (frente, entrecejo, patas de gallo, etc.)\n• S/700 tratamiento FULL FACE (todas las zonas — tercio superior + medio + inferior)\n\nLa Dra. evalúa qué zonas trabajar según tu caso en la consulta gratuita (30 min, sin compromiso).\n\n¿Quieres agendar?`,
  greeting_acido: n => `Hola${n?' '+n:''} ☺️ Gracias por escribirnos a Livskin.\n\nSoy Yossie, asistente de la Dra. Claudia Delgado.\n\nVi que te interesa el Ácido Hialurónico — sirve para rinomodelación, ojeras, pómulos, labios o mentón. Da volumen, modela y los resultados son inmediatos. Dura 18-24 meses.\n\nEl precio se cotiza solo en consulta porque depende de la cantidad de producto. La consulta es gratuita.\n\n¿Agendamos?`,
  greeting_prp: n => `Hola${n?' '+n:''} ☺️ Gracias por escribirnos a Livskin.\n\nSoy Yossie, asistente de la Dra. Claudia Delgado.\n\nEl PRP (Plasma Rico en Plaquetas) usa tu propia sangre para regenerar la piel. Mejora calidad, grosor, textura. S/220 por sesión, son 3 sesiones (una cada mes).\n\n¿Quieres agendar consulta gratuita?`,
  greeting_limpieza: n => `Hola${n?' '+n:''} ☺️ Gracias por escribirnos a Livskin.\n\nSoy Yossie, asistente de la Dra. Claudia Delgado.\n\nLa Limpieza Facial Profunda parte desde S/70 (básica) hasta S/120 (premium). Dura 45-60 min, sin recuperación, recomendada cada 3-4 semanas.\n\nIdeal para conocer a la Dra. y mantener tu piel limpia + radiante.\n\n¿Agendamos?`,
  greeting_default: n => `Hola${n?' '+n:''} ☺️ Gracias por escribirnos a Livskin.\n\nSoy Yossie, asistente de la Dra. Claudia Delgado.\n\nLa Dra. es Médico Cirujano colegiada (CMP 091029) con 10+ años de experiencia en Cusco.\n\n¿Qué tratamiento te interesa? Tenemos Botox, Ácido Hialurónico, PRP, Limpieza Facial y más. La consulta es gratuita.`,
  greeting_recurrente: n => `Hola${n?' '+n:''} ☺️ Qué bueno saber de ti.\n¿En qué te ayudo?`,
  painpoint_miedo_dolor: 'Todo duele un poquito ☺️\nPero los resultados valen — la Dra. usa técnicas suaves y aplica anestesia local cuando es necesario.\n\n¿Quieres agendar consulta para que te explique según tu caso?',
  painpoint_miedo_cambio: 'Esta es una pregunta clave para la Dra. ☺️\n\nSu filosofía es opuesta a "cambiar el rostro": trabaja sobre TUS facciones, devolviendo lo que tenías antes. No cambia estructura, no bloquea gestos.\n\nLa Dra. usa sus propios productos — ella misma es ejemplo de resultados naturales.\n\n¿Te gustaría conocerla en consulta gratuita?',
  painpoint_precio_alto: 'Sí, los productos médicos certificados tienen un costo ☺️\n\nLa Dra. usa marcas como Reach (Botox) y Yvoire (Ácido Hialurónico) — puedes verificar precios online si quieres comparar.\n\nTambién hay versiones más económicas que te puede ofrecer en consulta — no tienen exactamente el mismo resultado pero pueden funcionar para tu caso.',
  painpoint_desconfianza: 'Totalmente válida la pregunta ☺️\n\nLa Dra. Claudia Delgado es Médico Cirujano colegiada — CMP 091029. Cursa la Maestría en Medicina Estética en la Universidad Científica del Sur.\n\n10+ años de experiencia, formación intensiva en Argentina, USA y Colombia.',
  painpoint_inseguridad_social: 'Mira, los varones casi nunca notan nada ☺️\nY si lo notan, tienes suerte.\n\nLa filosofía de la Dra. es justo esa — que el cambio se vea natural, sin que parezca que te hiciste algo.',
  painpoint_timing_edad: 'La edad ideal depende de tu genética y cómo gesticulas ☺️\n\nCada persona envejece distinto. La Dra. lo evalúa caso por caso.\n\n¿Quieres una evaluación gratuita en consulta?',
  painpoint_falta_tiempo: 'La Dra. tiene flexibilidad horaria ☺️\n\nAtiende desde temprano hasta tarde, incluso domingos previa coordinación.\n\n¿Qué horario te queda mejor?',
  painpoint_comparacion: 'Cada clínica tiene sus propios productos y precios ☺️\n\nLo que cambia: la marca del producto, los años de experiencia de quien lo aplica, y el seguimiento.\n\nLa Dra. Claudia usa marcas médicas certificadas (Reach, Yvoire). La Dra. puede ajustar entre S/20-30 según tu caso en consulta.',
  painpoint_distancia: 'La Dra. tiene consideraciones para pacientes de lejos ☺️\n\nPuede agendar horarios que te acomoden, concentrar tratamientos en una visita, o lo que necesites.\n\n¿De dónde vienes?',
  painpoint_cuotas: 'Por ahora el pago es al momento del tratamiento ☺️\n\nAceptamos Yape, Plin, transferencia y efectivo.\n\nSi te vuelves cliente recurrente, la Dra. puede manejar crédito caso por caso.',
  painpoint_no_sabe: 'Entendido ☺️\n\nPara eso es la consulta gratuita — la Dra. evalúa tu caso específico y te recomienda los tratamientos. Dura 30 min, sin compromiso.\n\n¿Quieres agendar?',
  painpoint_primera_vez: 'Bienvenida ✨ Es normal tener dudas la primera vez.\n\nLa Dra. tiene 10+ años trabajando con pacientes primerizos. Te explica todo en detalle antes de cualquier decisión.\n\nLa consulta es gratuita y sin compromiso. ¿Agendamos?',
  ask_price_botox: 'Los precios del Botox son ☺️\n\n• S/250 por zona individual\n• S/700 tratamiento FULL FACE (todas las zonas)\n\nLa Dra. evalúa qué zonas trabajar según tu caso en la consulta gratuita.\n\n¿Quieres agendar?',
  ask_price_acido: 'El Ácido Hialurónico se cotiza solo en consulta ☺️\n\nEs porque el precio depende mucho de la cantidad de producto que cada persona necesita.\n\nLa consulta con la Dra. es gratuita y dura 30 min. ¿Agendamos?',
  ask_price_prp: 'El PRP está en S/220 por sesión ☺️\nSon 3 sesiones, una cada mes.\n\nO S/200 solo infiltrado (sin Dermapen).\n\n¿Te gustaría agendar consulta gratuita?',
  ask_price_limpieza: 'La Limpieza Facial parte desde S/70 (básica) hasta S/120 (premium) ☺️\n\nDura 45-60 min, recomendada cada 3-4 semanas.\n\n¿Agendamos?',
  ask_price_default: 'Te cuento los rangos ☺️\n\n• Botox: S/250 por zona / S/700 full face\n• Ácido Hialurónico: solo en consulta\n• PRP: S/200-250\n• Limpieza Facial: S/70-120\n• Esperma de Salmón: S/250-500\n• Exosomas: S/250-600\n\nLa consulta con la Dra. es gratuita.',
  escalate_contraindication: n => `${n||'Hola'} ☺️ Este caso lo evalúa directamente la Dra. Claudia.\n\nCada condición médica requiere análisis individual.\n\nLe paso tu consulta y te responde apenas pueda.`,
  escalate_red_flag: n => `${n||''} ☺️ Te paso con la Dra. Claudia para que coordine directamente contigo.\n\nTe responde en breve.`,
  escalate_ask_human: n => `Claro ☺️ Le paso a la Dra. Claudia para que vea tu mensaje y te responda directamente.\n\nMientras tanto, si quieres adelantarme algo sobre lo que buscas, lo anoto para ella.`,
  escalate_low_conf: n => `${n||''} ☺️ Para responderte bien, te paso directo con la Dra.\n\nTe responde apenas pueda.`,
  confirm_ack: n => `${n?'Listo '+n:'Listo'} ☺️\nLe paso a la Dra. y te confirmo el horario en breve.`,
  reject_ack: 'Oki, entendido ☺️\nSi más adelante quieres conversar, aquí estoy. Estamos en contacto.',
  cancel_ack: 'Oki, entendido ☺️\nSi quieres volver a agendar, aquí estoy.',
  reschedule_req: 'Tranquila ☺️ ¿Cuándo te queda mejor? La Dra. tiene flexibilidad — temprano, tarde, domingos.',
  info_direccion: '📍 Estamos en Urbanización La Florida O-7, Wanchaq, Cusco.\n\nDetrás del templo de los Mormones, media cuadra encima.\n\nParking gratis frente al consultorio ☺️',
  info_pagos: 'Aceptamos Yape, Plin, transferencia y efectivo ☺️\n\nEl pago es al momento del tratamiento.',
  info_horario: 'La Dra. atiende previa coordinación con flexibilidad — desde temprano hasta tarde, incluso domingos.\n\n¿Qué día y horario te queda mejor?',
  default_helpful: 'Cuéntame un poquito más sobre qué buscas ☺️\n\n¿Es para suavizar líneas, dar volumen, mejorar luminosidad o algo específico? Con eso te oriento mejor.',
};

// === MAIN ===
const body = $input.first().json.body || {};
const entries = body.entry || [];
const outputs = [];

for (const entry of entries) {
  for (const change of (entry.changes || [])) {
    const value = change.value || {};
    const messages = value.messages || [];
    for (const msg of messages) {
      const from = msg.from;
      const messageId = msg.id;
      const timestamp = msg.timestamp;
      const type = msg.type;
      let bodyText = '';
      if (type === 'text') bodyText = msg.text?.body || '';
      else if (type === 'button') bodyText = msg.button?.text || '';
      else if (type === 'interactive') bodyText = msg.interactive?.button_reply?.title || msg.interactive?.list_reply?.title || '';

      // Referral del Click-to-WhatsApp (Meta Ads)
      const referral = msg.referral || msg.context?.referral || null;

      // Detección
      const intentRes = detectIntent(bodyText);
      const product = detectProduct(referral ? (referral.headline + ' ' + (referral.body||'')) : bodyText);
      const redFlag = detectRedFlag(bodyText);
      const painpoint = detectPainpoint(bodyText);
      const infoType = detectInfo(bodyText);

      // Dispatch
      let actionType, responseText, auditReason, escalate = false;
      const name = ''; // TODO: lookup ERP en próximo nodo

      if (redFlag === 'contraindication') {
        actionType = 'escalate_contraindication';
        responseText = COPY.escalate_contraindication(name);
        auditReason = 'contraindication_medical';
        escalate = true;
      } else if (redFlag) {
        actionType = 'escalate_red_flag';
        responseText = COPY.escalate_red_flag(name);
        auditReason = `red_flag_${redFlag}`;
        escalate = true;
      } else if (intentRes.intent === 'ask_human') {
        actionType = 'escalate_ask_human';
        responseText = COPY.escalate_ask_human(name);
        auditReason = 'user_requested_human';
        escalate = true;
      } else if (intentRes.intent === 'greeting' || intentRes.intent === 'unknown' || intentRes.intent === 'ask_info') {
        // First contact — pick by product
        if (product === 'botox') { actionType = 'greeting_botox'; responseText = COPY.greeting_botox(name); }
        else if (product === 'acido') { actionType = 'greeting_acido'; responseText = COPY.greeting_acido(name); }
        else if (product === 'prp') { actionType = 'greeting_prp'; responseText = COPY.greeting_prp(name); }
        else if (product === 'limpieza') { actionType = 'greeting_limpieza'; responseText = COPY.greeting_limpieza(name); }
        else { actionType = 'greeting_default'; responseText = COPY.greeting_default(name); }
        auditReason = `greeting_${product || 'default'}`;
      } else if (intentRes.intent === 'confirm') {
        actionType = 'confirm_ack';
        responseText = COPY.confirm_ack(name);
        auditReason = 'lead_confirmed';
      } else if (intentRes.intent === 'reject') {
        actionType = 'reject_ack'; responseText = COPY.reject_ack; auditReason = 'lead_rejected';
      } else if (intentRes.intent === 'cancel') {
        actionType = 'cancel_ack'; responseText = COPY.cancel_ack; auditReason = 'lead_cancelled'; escalate = true;
      } else if (intentRes.intent === 'reschedule') {
        actionType = 'reschedule_req'; responseText = COPY.reschedule_req; auditReason = 'lead_reschedule'; escalate = true;
      } else if (painpoint) {
        const k = `painpoint_${painpoint}`;
        actionType = k; responseText = COPY[k] || COPY.default_helpful; auditReason = k;
      } else if (intentRes.intent === 'ask_price') {
        if (product === 'botox') { actionType = 'ask_price_botox'; responseText = COPY.ask_price_botox; }
        else if (product === 'acido') { actionType = 'ask_price_acido'; responseText = COPY.ask_price_acido; }
        else if (product === 'prp') { actionType = 'ask_price_prp'; responseText = COPY.ask_price_prp; }
        else if (product === 'limpieza') { actionType = 'ask_price_limpieza'; responseText = COPY.ask_price_limpieza; }
        else { actionType = 'ask_price_default'; responseText = COPY.ask_price_default; }
        auditReason = actionType;
      } else if (infoType === 'direccion') { actionType = 'info_direccion'; responseText = COPY.info_direccion; auditReason = 'info_direccion'; }
      else if (infoType === 'pagos') { actionType = 'info_pagos'; responseText = COPY.info_pagos; auditReason = 'info_pagos'; }
      else if (infoType === 'horario') { actionType = 'info_horario'; responseText = COPY.info_horario; auditReason = 'info_horario'; }
      else if (intentRes.confidence < 0.5) {
        actionType = 'escalate_low_conf'; responseText = COPY.escalate_low_conf(name); auditReason = 'confidence_low'; escalate = true;
      } else {
        actionType = 'default_helpful'; responseText = COPY.default_helpful; auditReason = 'default_fallback';
      }

      console.log(`[YOSSIE] from=${from} intent=${intentRes.intent} product=${product} action=${actionType} escalate=${escalate}`);

      outputs.push({
        json: {
          from,
          messageId,
          timestamp,
          type,
          inbound_text: bodyText,
          referral: referral || null,
          referral_product: product,
          intent: intentRes.intent,
          confidence: intentRes.confidence,
          red_flag: redFlag,
          painpoint,
          info_type: infoType,
          action_type: actionType,
          response_text: responseText,
          audit_reason: auditReason,
          escalate,
          phone_number_id: value.metadata?.phone_number_id,
        }
      });
    }
  }
}

return outputs.length > 0 ? outputs : [{ json: { skip: true, reason: 'no_messages_to_process' } }];

parameters.query:
INSERT INTO wa_messages (
  phone_lead, direction, meta_message_id, body, message_type,
  intent, parsed_dates, meta_payload_raw, action_type, audit_reason
) VALUES (
  $1, 'inbound', $2, $3, $4,
  $5, $6::jsonb, $7::jsonb, $8, $9
) ON CONFLICT (meta_message_id) DO NOTHING
RETURNING id;

INSERT INTO wa_conversation_state (
  phone_lead, state, last_inbound_at, last_action_type, message_count, agent_paused, context_json
) VALUES (
  $1, 'open', NOW(), $2, 1, false, $3::jsonb
) ON CONFLICT (phone_lead) WHERE state != 'closed' DO UPDATE SET
  last_inbound_at = NOW(),
  last_action_type = EXCLUDED.last_action_type,
  message_count = wa_conversation_state.message_count + 1,
  state = CASE WHEN EXCLUDED.context_json->>'escalate' = 'true' THEN 'escalated' ELSE wa_conversation_state.state END,
  updated_at = NOW();
